fn legacy_rc4_uses_object_and_generation_and_truncates_to_ten_bytes() {
    let handler = standard_handler(R2.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(None, trailer.id()).unwrap();

    // 既知の R2 ファイル鍵に番号をリトルエンディアンで連結し、Python の hashlib で照合した。
    for (number, generation, expected) in [
        (7, 0x1234, b"\xf1\x2f\xa0\xa4\x93\xe0\x98\x62\xb8\x9f"),
        (8, 0x1234, b"\xac\x0b\xec\xab\xa7\xe5\x74\x66\x52\x21"),
        (7, 0x1235, b"\x78\x93\xd9\x0c\x35\x7a\x5d\x7f\xaa\x6d"),
    ] {
        let target = indirect(number, generation, EncryptedValueKind::String);
        let ObjectDecryption::Rc4(key) = handler.object_decryption(&auth, target).unwrap() else {
            panic!("V1 の文字列には RC4 の鍵が必要");
        };
        assert_eq!(key.as_bytes(), expected);
    }
}

fn algorithm_one_uses_only_the_low_three_object_number_bytes() {
    let handler = standard_handler(R2.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(None, trailer.id()).unwrap();

    // 0xff_ffff は 3 バイトの上限。0x100_0000 の下位 3 バイトは 00 00 00。
    for (number, generation, expected) in [
        (
            0xff_ffff,
            0xffff,
            b"\x42\x30\xf5\x89\xe6\xb9\x12\x90\x8f\xad",
        ),
        (
            0x100_0000,
            0xffff,
            b"\x92\x2d\x06\x64\x3c\x7b\x68\x91\x6d\xb8",
        ),
        (
            0xab_cdef,
            0x1234,
            b"\xf6\x64\x60\x5f\x8d\x58\x8d\xe7\xb2\x13",
        ),
        (
            0x1ab_cdef,
            0x1234,
            b"\xf6\x64\x60\x5f\x8d\x58\x8d\xe7\xb2\x13",
        ),
    ] {
        let target = indirect(number, generation, EncryptedValueKind::Stream);
        let ObjectDecryption::Rc4(key) = handler.object_decryption(&auth, target).unwrap() else {
            panic!("V1 のストリームには RC4 の鍵が必要");
        };
        assert_eq!(key.as_bytes(), expected);
    }
}

fn aesv3_reuses_the_same_authenticated_file_key_for_distinct_objects() {
    let handler = standard_handler(R5.as_bytes());
    let auth = handler.authenticate(Some(b"user-r5"), None).unwrap();
    let file_key = auth.key().as_aes256().unwrap();

    for (number, generation, kind) in [
        (7, 0, EncryptedValueKind::String),
        (0x100_0000, 8, EncryptedValueKind::Stream),
    ] {
        let target = indirect(number, generation, kind);
        let ObjectDecryption::Aes256(key) = handler.object_decryption(&auth, target).unwrap()
        else {
            panic!("AESV3 の場合はファイル暗号鍵を使う");
        };
        assert!(std::ptr::eq(key, file_key));
    }
}

fn stream_and_string_filters_select_salted_aes128_and_unsalted_rc4() {
    let source = R4_CLEAR_METADATA
        .replace("/CF << /StdCF", "/CF << /Legacy << /CFM /V2 >> /StdCF")
        .replace("/StrF /StdCF", "/StrF /Legacy");
    let handler = standard_handler(source.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();

    let stream = indirect(7, 0x1234, EncryptedValueKind::Stream);
    let ObjectDecryption::Aes128(aes) = handler.object_decryption(&auth, stream).unwrap() else {
        panic!("/StmF の AESV2 が選ばれる");
    };
    let string = indirect(7, 0x1234, EncryptedValueKind::String);
    let ObjectDecryption::Rc4(rc4) = handler.object_decryption(&auth, string).unwrap() else {
        panic!("/StrF の V2 が選ばれる");
    };

    // 同じ ObjectId と既知の R4 ファイル鍵で、sAlT の有無だけを変えて hashlib で照合した。
    assert_eq!(
        aes.as_bytes(),
        b"\x1b\x66\xd7\xe5\xff\xda\x93\xe9\xbb\x90\x89\x2a\xb0\xe0\x50\x27"
    );
    assert_eq!(
        rc4.as_bytes(),
        b"\xa8\x1a\xbb\xe4\x02\x51\x16\xeb\xda\x01\xd9\x65\x26\x39\xdd\xee"
    );
}

fn identity_and_no_encryption_method_return_no_key() {
    let trailer = parse_trailer(TRAILER);
    for selectors in [
        "/StrF /Identity /StmF /Identity",
        "",
        "/StrF /Clear /StmF /Default",
    ] {
        let source = R4_CLEAR_METADATA
            .replace("/StmF /StdCF /StrF /StdCF", selectors)
            .replace(
                "/CF << /StdCF",
                "/CF << /Clear << /CFM /None >> /Default << >> /StdCF",
            );
        let handler = standard_handler(source.as_bytes());
        let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();

        for kind in [EncryptedValueKind::Stream, EncryptedValueKind::String] {
            let target = indirect(7, 0, kind);
            assert!(matches!(
                handler.object_decryption(&auth, target).unwrap(),
                ObjectDecryption::None
            ));
        }
    }
}

fn undefined_stream_and_string_filter_fail_during_dictionary_parsing() {
    for (selector, key) in [("/StmF", EncryptKey::StmF), ("/StrF", EncryptKey::StrF)] {
        let source = R4_CLEAR_METADATA.replace(
            &format!("{selector} /StdCF"),
            &format!("{selector} /Unknown"),
        );
        assert_eq!(
            encrypt_err(source.as_bytes()).kind(),
            &EncryptErrorKind::UndefinedCryptFilter {
                key,
                name: PdfName::from("Unknown")
            },
        );
    }
}

fn object_stream_container_gets_a_key_but_its_members_do_not() {
    let handler = standard_handler(R4_CLEAR_METADATA.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();

    let container = indirect(12, 0, EncryptedValueKind::Stream);
    assert!(matches!(
        handler.object_decryption(&auth, container).unwrap(),
        ObjectDecryption::Aes128(_)
    ));
    assert!(matches!(
        handler
            .object_decryption(&auth, ObjectDecryptionTarget::InObjectStream)
            .unwrap(),
        ObjectDecryption::None
    ));
}

fn rejects_aes128_when_the_file_key_is_shorter_than_128_bits() {
    // R4 の 40 ビット鍵で /U の照合は通るが、AESV2 が要求する 128 ビットを満たさない。
    let source = b"<< /Filter /Standard /V 4 /R 4 /Length 40 /P -4
        /O <3c482162008fafcb228b7db3c43a1090bc5b56e9b1556e89fc0656fd291f4908>
        /U <d3b1553015c7d57ed4c8a35b0f084ee900000000000000000000000000000000>
        /CF << /StdCF << /CFM /AESV2 >> >> /StmF /StdCF >>";
    let handler = standard_handler(source);
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();
    let target = indirect(7, 0, EncryptedValueKind::Stream);

    assert_eq!(
        handler.object_decryption(&auth, target).unwrap_err(),
        ObjectKeyError::IncompatibleFileKey {
            method: CryptFilterMethod::AesV2,
            length: 5,
        }
    );
}

pub fn object_decryption<'key>(
    &self,
    file_key: &'key AuthenticatedFileKey,
    target: ObjectDecryptionTarget,
) -> Result<ObjectDecryption<'key>, ObjectKeyError> {
    let ObjectDecryptionTarget::Indirect { id, kind } = target else {
        return Ok(ObjectDecryption::None);
    };

    let method = self.algorithm().crypt_filter_method(kind);

pub fn object_decryption<'key>(
    &self,
    file_key: &'key AuthenticatedFileKey,
    target: ObjectDecryptionTarget,
) -> Result<ObjectDecryption<'key>, ObjectKeyError> {
    let ObjectDecryptionTarget::Indirect { id, kind } = target else {
        return Ok(ObjectDecryption::None);
    };

(CryptFilterMethod::AesV2, FileEncryptionKey::Legacy(key))
    if key.as_bytes().len() == AES128_KEY_LEN =>
{
    let bytes = key.object_key_hash(id, AES128_KEY_SALT);
    Ok(ObjectDecryption::Aes128(Aes128ObjectKey(bytes)))
}
(CryptFilterMethod::AesV3, FileEncryptionKey::Aes256(key)) => {
    Ok(ObjectDecryption::Aes256(key))
}

impl StandardAlgorithm {
    fn crypt_filter_method(&self, kind: EncryptedValueKind) -> CryptFilterMethod {
        let filters = match self {
            Self::V1R2 | Self::V1R3 | Self::V2R3 { .. } => return CryptFilterMethod::V2,
            Self::V4R4 { crypt_filters, .. }
            | Self::V5R5 { crypt_filters, .. }
            | Self::V5R6 { crypt_filters, .. } => crypt_filters,
        };
        let selector = match kind {
            EncryptedValueKind::String => filters.string(),
            EncryptedValueKind::Stream => filters.stream(),
        };

        // 名前付きの /StrF と /StmF は解析時に存在を検証済みなので、ここでの欠落は /Identity。
        filters
            .get(selector)
            .map_or(CryptFilterMethod::None, CryptFilter::method)

impl LegacyFileKey {
    fn object_key_hash(&self, id: ObjectId, suffix: &[u8]) -> [u8; DIGEST_LEN] {
        // Algorithm 1 は 24 ビットを超える番号でも下位 3 バイトだけを使う。
        let [low, middle, high, ..] = id.object_number().value().to_le_bytes();
        let generation = id.generation_number().value().to_le_bytes();

        let mut md5 = Md5::new();
        md5.update(self.as_bytes());
        md5.update(&[low, middle, high]);
        md5.update(&generation);
        md5.update(suffix);
        md5.finalize()
    }
